import{_ as a,c as e,o,a2 as r}from"./chunks/framework.CHomSxuB.js";const c=JSON.parse('{"title":"2. 公告排雷：LLM 剔除利空龙头有用吗（Step 3）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/2-公告排雷.md","filePath":"A股量化验证/2-公告排雷.md"}'),d={name:"A股量化验证/2-公告排雷.md"};function l(n,t,s,i,h,p){return o(),e("div",null,t[0]||(t[0]=[r('<h1 id="_2-公告排雷-llm-剔除利空龙头有用吗-step-3" tabindex="-1">2. 公告排雷：LLM 剔除利空龙头有用吗（Step 3） <a class="header-anchor" href="#_2-公告排雷-llm-剔除利空龙头有用吗-step-3" aria-label="Permalink to &quot;2. 公告排雷：LLM 剔除利空龙头有用吗（Step 3）&quot;">​</a></h1><blockquote><p>结论：<strong>排雷本身无正贡献（甚至微损）</strong> —— 🔒 已证伪 卷宗：<code>bench-step3-20260818.md</code>（A/B 组配对检验）</p></blockquote><h2 id="故事与反故事" tabindex="-1">故事与反故事 <a class="header-anchor" href="#故事与反故事" aria-label="Permalink to &quot;故事与反故事&quot;">​</a></h2><p>市场叙事：龙头股一旦公告&quot;股东大额减持/利空&quot;，次日容易核按钮，应该在打板前<strong>剔除</strong>。 Step 3 验证：用 LLM 扫描信号股窗口内公告，把高危利空（L1 级：大额减持等）剔除后， 剩下的样本是否<strong>显著更好</strong>？</p><h2 id="协议-v0-4-冻结" tabindex="-1">协议（V0.4 冻结） <a class="header-anchor" href="#协议-v0-4-冻结" aria-label="Permalink to &quot;协议（V0.4 冻结）&quot;">​</a></h2><ul><li>A 组 = 原始可成交样本（n=105）</li><li>剔除 = LLM 判定高危（L1 级利空公告，含大额减持等），上限损耗率 15%</li><li>B 组 = 排雷后样本</li><li>判据：B 组 Ev(Close)/胜率/CVaR95 是否优于 A 组（配对比较，bootstrap 10,000 次）</li></ul><h2 id="实测结果-243-交易日" tabindex="-1">实测结果（243 交易日） <a class="header-anchor" href="#实测结果-243-交易日" aria-label="Permalink to &quot;实测结果（243 交易日）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>A 组（n=105）</th><th>B 组（n=102）</th><th>变化</th></tr></thead><tbody><tr><td>均值 Ev(Close)</td><td>0.0269</td><td>0.0257</td><td><strong>−0.0011（变差）</strong></td></tr><tr><td>胜率 P(Ev&gt;0)</td><td>0.6571</td><td>0.6471</td><td>−0.0101（变差）</td></tr><tr><td>中位数 Ev(Close)</td><td>0.0421</td><td>0.0421</td><td>0.0000</td></tr><tr><td>CVaR95</td><td>−0.1054</td><td>−0.1054</td><td>0.0000</td></tr></tbody></table><p>LLM 在 105 只里挑出 3 只高危剔除（损耗 2.9%）：智能自控、风华高科、和远气体 （均为股东减持类公告）。剔除后样本<strong>均值反而微降、胜率下降 1pp、尾部毫无改善</strong>。</p><h2 id="裁决" tabindex="-1">裁决 <a class="header-anchor" href="#裁决" aria-label="Permalink to &quot;裁决&quot;">​</a></h2><p>排雷<strong>没有带来任何正向增量</strong>——被 LLM 判为&quot;高危&quot;的那 3 只，事后看并不比其他样本更差。 在样本量有限的短线宇宙里，&quot;用公告利空预筛龙头&quot;这个动作的净贡献 ≈ 0 甚至为负。</p><p><strong>认知点</strong>：公告级利空信息，在涨停板生态里大概率已被价格提前消化（能封板的本身就是 &quot;无视利空&quot;的强势票）；用 LLM 当&quot;第二层过滤器&quot;只是徒增损耗。</p><h2 id="处置" tabindex="-1">处置 <a class="header-anchor" href="#处置" aria-label="Permalink to &quot;处置&quot;">​</a></h2><ul><li>排雷动作从主流程降级；Step 3 结论封存。</li><li>保留条件已写入协议：若未来样本扩至 n≥200 且排雷组 CVaR95 显著收窄（BH p&lt;0.05）， 可由新协议版本重新启用——在那之前不再触碰。</li></ul><hr><p><strong>验证线汇总导航</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · <a href="/A股量化验证/3-连板接力与情绪闸门.html">下一线：连板接力与情绪闸门</a></p>',16)]))}const _=a(d,[["render",l]]);export{c as __pageData,_ as default};
